$ErrorActionPreference = 'Stop'
$solution = Split-Path $PSScriptRoot -Parent
function ReadSource($relative) {
    Get-Content -Raw -Encoding UTF8 (Join-Path $solution $relative)
}
function Require($condition, $message) {
    if (-not $condition) { throw $message }
}
$client = ReadSource 'PixelTool/AI/CodexChatClient.cs'
$direct = ReadSource 'PixelTool/AI/ChatGptChatClient.cs'
$auth = ReadSource 'PixelTool/AI/ChatGptSignIn.cs'
$tools = ReadSource 'PixelTool/AI/ChatGptProjectTools.cs'
$graphics = ReadSource 'PixelTool/Tool/GraphicsWindow/GraphicsWindow.cs'
$history = ReadSource 'PixelTool/AI/CodexChatHistory.cs'
$view = ReadSource 'PixelTool/Tool/AIChatWindow/AIChatWindow.xaml.cs'
Require ($view.Contains('ObservableCollection<TranscriptMessage> _transcript') -and -not $view.Contains('TranscriptBox.Text = string.Join')) 'Resizing chat must not reflow one TextBox containing the entire history'
Require ($view.Contains('_history.Messages.Where(m => m.Role is') -and $view.Contains('var message = visibleMessages[i]') -and -not $view.Contains('_history.Messages.RemoveAll')) 'Only conversation messages should be displayed without deleting internal history'
$luaEditor = ReadSource 'PixelTool/Tool/EditorLuaWindow/LuaEditor.xaml.cs'
Require ($graphics.Contains('Focusable = true') -and $graphics.Contains('SetFocus(_childHwnd)') -and $graphics.Contains('IntPtr focus = GetFocus()')) 'Scene View must own real keyboard focus rather than leaving it in Lua'
Require ($luaEditor.Contains('LuaEditor.PreviewTextInput +=') -and $luaEditor.Contains('CommandManager.AddPreviewExecutedHandler') -and $luaEditor.Contains('if (IsSceneGameInputActive)')) 'Lua must guard typed text and editing commands while Scene View owns game input'
$main = ReadSource 'PixelTool/MainWindow.xaml.cs'
Require ($main.Contains('EditorToolbar.IsPlayMode && GraphicsWindow.HasNativeKeyboardFocus')) 'Game input guard must require both play mode and native Scene View focus'
$toolbar = ReadSource 'PixelTool/Tool/ToolbarWindow/ToolbarWindow.xaml.cs'
[xml]$xaml = ReadSource 'PixelTool/Tool/AIChatWindow/AIChatWindow.xaml'
$chatButtons = $xaml.SelectSingleNode('//*[local-name()="UserControl.Resources"]/*[local-name()="Style" and @TargetType="Button"]')
Require ($chatButtons.BasedOn -eq '{StaticResource PixelToolButton}' -and $chatButtons.SelectSingleNode('./*[local-name()="Setter" and @Property="Foreground"]').Value -eq '#F2F5F9') 'Chat buttons must use the shared dark hover template with a legible default foreground'
Require ($xaml.OuterXml.Contains('Binding IsUser') -and $xaml.OuterXml.Contains('#9AD0FF')) 'User questions must use a distinct foreground from AI answers'
$dock = ReadSource 'PixelTool/Docking/DockWorkspace.cs'
Require ($dock.Contains('DockNode.Split(DockNode.Pane("LuaEditor"), DockNode.Pane("AIChat"), true, .6)')) 'Default chat pane must be beside the Lua editor'
Require ($main.Contains('ShowAIChat(false, placeBesideLua: true)') -and $main.Contains('dockManager.ShowDocument("AIChat", activate)')) 'Startup and toolbar must use the same dock activation path'
Require ($main.Contains('dockManager.Register("AIChat",') -and $main.Contains('_aiChat);') -and $dock.Contains('documents.Add(id,')) 'Register one chat instance instead of recreating it while docking'
Require ($toolbar.Contains('ShowAIChat()') -and $main.Contains('dockManager.Dispose()')) 'Toolbar and shutdown must use the custom dock workspace'
Require ($view.Contains('new ChatGptChatClient()') -and -not $view.Contains('new CodexChatClient()') -and -not $direct.Contains('Process.Start')) 'Default connection must not require a Codex executable'
Require ($auth.Contains('dynamic_agent_client') -and $auth.Contains('code_verifier') -and $auth.Contains('code_challenge_method') -and $auth.Contains('nonce')) 'Direct sign-in must use dynamic registration, state/nonce and PKCE'
Require ($view.Contains('type = "chatgpt"') -and $view.Contains('account.GetProperty("type").GetString() != "chatgpt"')) 'Chat must refuse API-key inference'
Require ($auth.Contains('ProtectedData.Protect') -and $auth.Contains('DataProtectionScope.CurrentUser') -and $auth.Contains('SetAccessRuleProtection(true, false)')) 'Credentials must use DPAPI and private ACL, separate from chat history'
Require (-not $auth.Contains('query["id_token_hint"]') -and -not $auth.Contains('query["access_token"]')) 'Browser launch URLs must not contain tokens'
Require ($auth.Contains('rsa.VerifyData') -and $auth.Contains('validAudience') -and $auth.Contains('claims.GetProperty("nonce")') -and $auth.Contains('RequiredScope')) 'Verify the ID token and direct plan-use permission'
Require ($direct.Contains('https://api.openai.com/v1/') -and $direct.Contains('store = false, stream = true') -and -not $direct.Contains('backend-api')) 'Use the supported public Responses API without API-key fallback'
Require ($direct.Contains('type = "namespace", name = "pixeltool"') -and -not $direct.Contains('previous_response_id')) 'Plan-usage HTTP requires namespaced function tools and complete input replay'
Require ($view.Contains('"thread/resume"') -and $view.Contains('"turn/interrupt"')) 'Resume and stop controls missing'
Require ($tools.Contains('if (confirmChanges && !await approve(relative,') -and $direct.Contains('if (Approve == null')) 'Ask mode must show a write approval; automatic mode must skip only that dialog'
Require ($view.Contains('confirmActions = confirmCommands') -and $direct.Contains('allowEdits, confirmActions, ConfirmOperation') -and $direct.Contains('CommandExecutionPreference.ForTurn(confirmActions)')) 'Snapshot approval choice must reach both model instructions and the actual file operation'
$console = ReadSource 'PixelTool/Tool/ConsoleWindow/ConsoleWindow.xaml.cs'
$editor = ReadSource 'PixelTool/Tool/EditorLuaWindow/LuaEditor.xaml.cs'
Require ($tools.Contains('Tool("reimport_project"') -and $tools.Contains('Tool("read_editor_logs"')) 'Editor reimport and incremental log tools must be exposed'
Require ($view.Contains('ReimportForAiAsync(token)).Task.Unwrap()') -and $direct.Contains('if (!allowEdits) result =') -and $direct.Contains('ReadEditorLogs(')) 'Route reimport through the UI and keep edit permission while logs remain read-only'
Require ($graphics.Contains('_pendingUiChanges.Enqueue') -and $graphics.Contains('_afterFrameActions.Enqueue') -and $graphics.IndexOf('PixelEngineNative.UpdateEngine();') -lt $graphics.IndexOf('while (_afterFrameActions.TryDequeue')) 'Reimport completion must follow the engine update, not just queue submission'
Require ($main.Contains('HasUnsavedFiles == true') -and $editor.Contains('internal bool HasUnsavedFiles') -and $main.Contains('LuaDebugSession.IsInspecting')) 'Do not silently save or reimport dirty buffers or a paused debugger'
Require ($console.Contains('lock (_captureLock)') -and $console.Contains('cleared = afterCursor < _clearedThroughCursor') -and $console.Contains('hasMore =') -and $console.Contains('truncated =')) 'Logs must include pending captures, pagination and lost-history flags'
Require ($tools.IndexOf('if (!allowEdits)') -lt $tools.IndexOf('if (confirmChanges &&') -and $direct.Contains('!p.TryGetProperty("confirmActions", out var confirm) || confirm.GetBoolean()')) 'Automatic approval must preserve edit permission; absent preferences must ask by default'
Require ($view.Contains('if (AllowEdits.IsChecked != true) return false;') -and $view.Contains('type = "readOnly"')) 'Read-only mode must not approve elevated commands'
Require ($view.Contains('networkAccess = false') -and $view.Contains('writableRoots = new[] { _project }')) 'Writable scope must be the selected project only'
Require ($tools.Contains('FileAttributes.ReparsePoint') -and $tools.Contains('Path.IsPathRooted') -and $tools.Contains('Matches(latest, expected)')) 'File tools must reject outside/reparse paths and stale replacements'
Require (-not $tools.Contains('Process.Start') -and -not $direct.Contains('Process.Start')) 'Do not expose unsandboxed arbitrary command execution'
foreach ($assetTool in @('create_asset_folder', 'inspect_asset', 'copy_asset', 'import_asset', 'create_png_asset')) {
    Require ($tools.Contains('Tool("' + $assetTool + '"')) "Asset tool must be exposed: $assetTool"
}
Require ($tools.Contains('PixelFormats.Bgra32') -and $tools.Contains('PngBitmapEncoder') -and $tools.Contains('width > 1024') -and $tools.Contains('GetArrayLength() > 4096')) 'PNG assets must preserve alpha with bounded drawing dimensions/work'
Require ($tools.Contains('ResolveAsset(relative)') -and $tools.Contains('File.Move(staging, path, overwrite: false)')) 'New assets must stay in Asset and must never overwrite existing files'
Require ($view.Contains('new Microsoft.Win32.OpenFileDialog') -and $view.Contains('_client.PickAsset =') -and $tools.Contains('await pickAsset().WaitAsync(token)')) 'Outside assets require a user-selected file instead of model-supplied outside paths'
Require ($history.Contains('SHA256.HashData') -and $history.Contains('"AIChat", key + ".json"')) 'Persist conversations separately per project'
Require ($history.Contains('File.Move(temporary, path, overwrite: true)')) 'History writes must use a temporary file'
Require ($main.Contains('_aiChat.DisposeChat()') -and $direct.Contains('_stop.Cancel()') -and $auth.Contains('_listener?.Close()')) 'Shutdown must cancel direct HTTP/login without waiting on UI callbacks'
Require ($main.Contains('_fpsTimer.Stop()')) 'Stop native FPS callbacks when the main window closes'
$fpsTick = $main.Substring($main.IndexOf('_fpsTimer.Tick +='), $main.IndexOf('_fpsTimer.Start()') - $main.IndexOf('_fpsTimer.Tick +='))
Require (-not $fpsTick.Contains('ApplyAvalonDockRuntimeTheme') -and $fpsTick.Contains('GetFPS()')) 'The periodic FPS timer must not repaint the docking theme'
Require (-not $main.Contains('ApplyAvalonDockRuntimeTheme') -and -not $dock.Contains('VisualTreeHelper.GetChildrenCount')) 'Docking must not rescan all content to repaint themes'
$graphics = ReadSource 'PixelTool/Tool/GraphicsWindow/GraphicsWindow.cs'
$focus = $graphics.Substring($graphics.IndexOf('private void OnThreadFilterMessage'), $graphics.IndexOf('protected override void DestroyWindowCore') - $graphics.IndexOf('private void OnThreadFilterMessage'))
Require ($focus.Contains('msg.hwnd != _childHwnd') -and $focus.Contains('!IsChild(_childHwnd, msg.hwnd)') -and $focus.IndexOf('msg.hwnd != _childHwnd') -lt $focus.IndexOf('this.Focus()')) 'Scene View must not steal focus from WPF controls or dropdown popup windows'
$destroy = $graphics.Substring($graphics.IndexOf('protected override void DestroyWindowCore'))
Require (-not $destroy.Contains('lock (_engineLock)')) 'Closing must not re-enter an unbounded native render lock after the timed join'
$guide = ReadSource 'PixelTool/AI/LuaApiGuide.md'
$loader = ReadSource 'PixelTool/AI/EngineGuide.cs'
[xml]$project = ReadSource 'PixelTool/PixelTool.csproj'
foreach ($name in @('AIRestrictions.md', 'EditorGuide.md', 'LuaApiGuide.md')) {
    $resource = @($project.Project.ItemGroup.EmbeddedResource | Where-Object Include -eq ('AI\' + $name))
    Require ($resource.Count -eq 1 -and $resource[0].LogicalName -eq ('PixelTool.AI.' + $name)) "Required guide must be embedded: $name"
    Require ($loader.Contains('"' + $name + '"')) "Loader must require guide: $name"
}
Require ($loader.Contains('Engine/*.lua') -and $loader.Contains('AGENTS.md')) 'API verification and supplementary project instructions must remain available'
Require ($loader.Contains('IsNullOrWhiteSpace(text)') -and $loader.Contains('throw new InvalidOperationException')) 'Missing or empty policy documents must fail closed'
Require (([regex]::Matches($view, 'developerInstructions = EngineGuide.Load\(\)')).Count -eq 2) 'Both new and resumed threads must receive developer instructions'
Require ($direct.Contains('instructions = _instructions') -and $direct.Contains('type == "response.completed"') -and $direct.Contains('if (!completed)')) 'Send developer guides on every inference and reject premature EOF'
Require ($direct.Contains('saved.Account != _account') -and $auth.Contains('FileShare.None') -and $auth.Contains('Current = session')) 'Keep account history bound and serialize refresh token rotation'
Require ($view.Contains('text = context + text') -eq $false -and $guide.Contains('Entity.CreateCamera()')) 'Application guides must not masquerade as user input'
Require ($view.Contains('"model/list"') -and $view.Contains('nextCursor') -and $view.Contains('includeHidden = false')) 'Model picker must use the paginated visible server catalog'
Require ($view.Contains('model = selected.Model') -and $view.Contains('effort = selected.DefaultEffort')) 'Turn must use selected model and compatible default effort'
Require ($history.Contains('public string? Model') -and $view.Contains('m.Model == savedModel')) 'Model choice must persist and restore per project'
Require ($xaml.SelectSingleNode('//*[@*[local-name()="Name"]="ModelBox"]') -ne $null -and $view.Contains('ModelBox.IsEnabled = !busy')) 'Model selector must be present and locked during a response'
$execution = ReadSource 'PixelTool/AI/CommandExecutionPreference.cs'
Require ($history.Contains('public bool ConfirmCommands { get; set; } = true;')) 'Existing histories must default to asking before commands'
Require ($history.Contains('public bool AllowEdits { get; set; }') -and $view.Contains('AllowEdits.IsChecked = _history.AllowEdits') -and $view.Contains('_history.AllowEdits = AllowEdits.IsChecked == true')) 'Edit permission checkbox must save and restore per project, with new projects remaining read-only'
Require ($xaml.SelectSingleNode('//*[@*[local-name()="Name"]="AllowEdits"]').Checked -eq 'AllowEditsChanged' -and $xaml.SelectSingleNode('//*[@*[local-name()="Name"]="AllowEdits"]').Unchecked -eq 'AllowEditsChanged') 'Both checkbox states must persist immediately'
Require ($view.Contains('AccountDetails.Visibility = Visibility.Collapsed') -and $view.Contains('ToggleAccountDetails') -and $view.Contains('Loaded += RestoreConnection')) 'Connected account controls must collapse behind account management and restore on load'
Require ($view.Contains('ConnectAsync(allowBrowserLogin: false)') -and $view.Contains('if (!allowBrowserLogin)') -and $auth.Contains('internal static bool HasSavedAccount')) 'Restore saved connections without opening a login browser automatically'
Require ($view.Contains('CommandApprovalBox.SelectedIndex = _history.ConfirmCommands ? 0 : 1') -and -not $view.Contains('CommandApprovalBox.IsEnabled = !busy')) 'Execution preference must restore and remain selectable during a turn'
Require ($view.Contains('bool confirmCommands = _history.ConfirmCommands;') -and $view.Contains('CommandExecutionPreference.ForTurn(confirmCommands)')) 'Snapshot command preference at send time so mid-turn changes apply only to the next message'
Require ($execution.Contains('string mode = confirmCommands') -and $execution -match '\uC2B9\uC778 \uB2F5\uBCC0' -and $execution -match '\uBCC4\uB3C4 \uC9C8\uBB38 \uC5C6\uC774') 'Execution modes must distinguish ask-first and scoped automatic execution'
Require ($execution.Contains('delete_asset_file') -and $execution -match '\uD504\uB85C\uADF8\uB7A8 \uC124\uCE58, \uCEE4\uBC0B, \uD478\uC2DC' -and $execution -match '\uBCC4\uB3C4 \uBA85\uC2DC\uC801') 'Asset deletion follows approval mode while install/commit/push still require separate consent'
Require (-not $view.Contains('approvalPolicy = "never"') -and -not $view.Contains('dangerFullAccess')) 'Automatic preference must not disable server approvals or sandboxing'
Require ($xaml.SelectSingleNode('//*[@*[local-name()="Name"]="ActivityBanner"]') -ne $null) 'Chat must have a prominent activity banner above the transcript'
$settings = $xaml.SelectSingleNode('//*[@*[local-name()="Name"]="SettingsPanel"]')
Require ($settings.Visibility -eq 'Collapsed' -and $settings.GetAttribute('Panel.ZIndex') -eq '10' -and $settings.SelectSingleNode('.//*[@*[local-name()="Name"]="ModelBox"]') -ne $null -and $settings.SelectSingleNode('.//*[@*[local-name()="Name"]="CommandApprovalBox"]') -ne $null) 'Model/account/approval settings must be an initially hidden overlay, not a tall header above chat'
Require ($view.Contains('Loaded += (_, _) => ScrollTranscriptToEnd()') -and $view.Contains('DispatcherPriority.ContextIdle') -and $view.Contains('IsVisibleChanged +=')) 'Scroll to latest history after the visible pane has completed its initial layout'
$progress = $xaml.SelectSingleNode('//*[@*[local-name()="Name"]="ResponseProgress"]')
Require ($progress.IsIndeterminate -eq '{Binding IsEnabled, ElementName=StopButton}') 'Busy animation must follow the same turn state as the stop button'
Require ($view.Contains('StopButton.Background') -and $view.Contains('SendButton.Content = busy')) 'Busy state must also highlight stop and change the send label'
Write-Output 'PASS: AI Chat docking, protocol, account-only access, approval, execution preference, activity display, history and shutdown contracts (static checks only)'
Require ($xaml.SelectSingleNode('//*[local-name()="Expander" and @IsExpanded="False"]') -ne $null -and $view.Contains('ReadCodeChange(message.Text)')) 'Saved code changes must have a collapsed expander while answers remain visible'
Require ($tools.IndexOf('savedCode?.Invoke') -gt $tools.IndexOf('File.Move(temporary, path, original != null)') -and $direct.Contains('type = "fileChange", path, before, after')) 'Only successfully saved code may emit before/after details'
Require ($tools.Contains('Tool("ask_choice"') -and $tools.Contains('maxItems = 5') -and $direct.Contains('options.Length is < 2 or > 5')) 'Choice tool must validate two to five options at schema and runtime boundaries'
Require ($view.Contains('TaskCreationOptions.RunContinuationsAsynchronously') -and $view.Contains('answer.TrySetCanceled(token)') -and $view.Contains('_choiceAnswer?.TrySetResult(answer)')) 'Choice answers must complete once without blocking the UI and cancel with the turn'
Require ($xaml.SelectSingleNode('//*[@*[local-name()="Name"]="ChoicePanel"]').Visibility -eq 'Collapsed' -and $xaml.SelectSingleNode('//*[@Click="ChooseOption"]') -ne $null -and $xaml.SelectSingleNode('//*[@Click="SubmitCustomChoice"]') -ne $null) 'Choice panel must offer buttons and custom text only while requested'
Require ($view.Contains('Stopwatch _requestClock') -and $view.Contains('Interval = TimeSpan.FromSeconds(1)') -and $view.Contains('_requestClock.Restart()') -and $view.Contains('_requestClock.Stop()') -and $view.Contains('_elapsedTimer.Stop()')) 'Request elapsed time must use a monotonic clock and stop the UI timer on completion and shutdown'
Require ($xaml.SelectSingleNode('//*[@*[local-name()="Name"]="ElapsedTimeText"]') -ne $null -and $view.Contains('if (busy || wasBusy) UpdateElapsedTime()') -and $view.Contains('_elapsedTimer.Tick += (_, _) => UpdateElapsedTime()')) 'Elapsed time must update independently of transcript and status messages'
$deleteStart = $tools.IndexOf('if (name is "delete_asset_file"')
$deleteEnd = $tools.IndexOf('if (name == "list_project_files")', $deleteStart)
$deleteTool = $tools.Substring($deleteStart, $deleteEnd - $deleteStart)
Require ($tools.Contains('Tool("delete_asset_file"') -and $deleteTool.Contains('path = ResolveAsset(relative)') -and $deleteTool.Contains('name == "delete_asset_file" && directory')) 'File deletion must require a file and all asset operations must remain below Asset'
Require ($deleteTool.Contains('if (!allowEdits)') -and $deleteTool.Contains('if (confirmChanges && !await approve(')) 'Deletion must respect edit permission and ask only in confirmation mode'
Require ($deleteTool.Contains('HashAssetPathAsync(relative, token).ConfigureAwait(false) != expectedHash') -and $deleteTool.Contains('canDeleteAssetFile(relative)') -and $view.Contains('HasUnsavedFile(Path.Combine(_project, relative))')) 'Asset operations must recheck contents and unsaved buffers in automatic and confirmation modes'
Require ($deleteTool.Contains('RecycleOption.SendToRecycleBin') -and -not $deleteTool.Contains('File.Delete(') -and -not $deleteTool.Contains('Directory.Delete(')) 'Asset deletion must use the existing recycle-bin mechanism, not permanent deletion'
Require ($tools.Contains('Tool("delete_asset_folder"') -and $tools.Contains('Tool("move_asset"') -and $deleteTool.Contains('AssetFileOperations.IsInside(destination, path)') -and $deleteTool.Contains('File.Move(path, destination, overwrite: false)')) 'Asset folder deletion and moves must reject recursive self-moves and overwrites'
Require ($tools.Contains('Path.TrimEndingDirectorySeparator(Resolve(relative))') -and $tools.Contains('ResolveAsset(Path.GetRelativePath(_root, entry))') -and $editor.Contains('AssetFileOperations.IsInside(file.Path, path)')) 'Asset root and linked/secret/unsaved subtree contents must be protected'
Require (-not $direct.Contains('round < 16') -and -not $direct.Contains('도구 호출 횟수 제한') -and $direct.Contains('while (true)') -and $direct.Contains('if (count >= 3) stalled =')) 'Fixed total tool round cap must be replaced by repeated-failure detection'
Require ($direct.Contains('if (fileChanged || IsAssetMutation(toolName, result))') -and $direct.Contains('repeatedFailures.Clear()') -and $direct.Contains('await SaveThreadAsync(token)') -and $direct.Contains('private static string? ToolFailure')) 'Real writes must reset failure history and stalled context must be retained'
Require ($view.Contains('IsNotice: message.Role ==') -and $view.Contains('AddWorkNotice(reason +') -and $view.Contains('if (wasBusy) AddWorkNotice(') -and $xaml.OuterXml.Contains('Binding IsNotice')) 'Failed, interrupted and disconnected work must remain visible as distinguished transcript notices'
Require ($direct.Contains('Emit("turn/toolWarning"') -and $view.Contains('method == "turn/toolWarning"') -and $direct.Contains('if (_userInterrupted) status = "interrupted"') -and $direct.Contains('ex.InnerException is TimeoutException')) 'Tool warnings and timeouts must be shown without mislabeling timeouts as user stops'
